import {UR} from './urdu.js';
export function detectVoiceIntent(text){const q=String(text).toLowerCase().replace(/ي/g,'ی').replace(/ك/g,'ک');if(/پانی|آبپاش|بارش|water|paani|pani|rain/.test(q))return 'water';if(/خرچ|لاگت|منافع|cost|kharch|profit|paisa/.test(q))return 'cost';if(/جانچ|ماہر|مشور|بیج|خریدار|check|seed|buyer/.test(q))return 'checks';if(/نقش|علاقہ|map|location/.test(q))return 'map';if(/خلاص|مدد|summary|help/.test(q))return 'summary';return null;}
export function buildSpokenSummary(context,topic='summary',language='ur'){
 if(!context?.valid)return language==='ur'?'پہلے کھیت کی معلومات درست کریں اور اسی مقام کے ناسا اعداد لائیں۔ پرانے مقام کے اعداد پر نیا مشورہ نہیں دیا جائے گا۔':'First correct the field inputs and retrieve NASA observations for its coordinates. The old location is not a basis for a new decision.';
 const {inputs:i,baseline:b,selectedRotation:r,financialScreen:f}=context,n=v=>Math.round(v).toLocaleString('en-US'),rotation=UR[r.name]||r.name;
 const water=language==='ur'?`${i.farm} کے لیے ${i.area} ہیکٹر، یعنی تقریباً ${(i.area*2.47105381).toFixed(1)} ایکڑ کا حساب۔ موجودہ فصلوں کی سالانہ تخمینی پانی کی ضرورت ${n(b.demand)} ملی میٹر ہے۔ ${rotation} کی ضرورت ${n(r.demand)} ملی میٹر ہے۔ بارش اور دستیاب آبپاشی کے بعد موجودہ ترتیب میں ${n(b.deficit)} اور منتخب ترتیب میں ${n(r.deficit)} ملی میٹر سالانہ کمی رہتی ہے۔ یہ حسابی موازنہ ہے، ناپی گئی پانی کی بچت نہیں۔ سالانہ صفر کمی بھی ہر موسم میں کافی پانی کی ضمانت نہیں۔`:`For ${i.farm}, ${i.area} hectares. Current annual indicative water demand is ${n(b.demand)} millimetres. ${r.name} asks for ${n(r.demand)}. After assumed rain and irrigation, the current rotation has a ${n(b.deficit)} millimetre annual gap; the selected rotation has ${n(r.deficit)}. These are modelled comparisons, not measured water savings. A zero annual gap does not guarantee water in every season.`;
 const cost=f?.status==='scenario'?(language==='ur'?`آپ کے درج کردہ خرچ کے مطابق پہلے سال کا فرق ${n(Math.abs(f.firstYearNetChange))} ${f.currency==='PKR'?'پاکستانی روپے':f.currency==='INR'?'بھارتی روپے':'امریکی ڈالر'} ${f.firstYearNetChange<0?'منفی':f.firstYearNetChange>0?'مثبت':'صفر'} ہے۔ ${f.firstYearNetChange<0?'خرچ پورا کرنے کے لیے بہتر خریدار قیمت یا کم تبدیلی کا خرچ ضروری ہے۔':'خریدار کی قیمت، پیداوار اور اصل بل کی مقامی تصدیق کریں۔'} یہ منافع کی پیش گوئی نہیں، آپ کے اندازوں پر حساب ہے۔`:`Your entered costs give a hypothetical first-year change of ${n(Math.abs(f.firstYearNetChange))} ${f.currency}, ${f.firstYearNetChange<0?'negative':f.firstYearNetChange>0?'positive':'zero'}. Check buyer prices, crop yields and actual bills locally. This is an assumption-based cost screen, not a profit forecast.`):(language==='ur'?'خرچ جانچنے کے لیے پانی نکالنے کا متغیر خرچ، فصل کے مارجن میں فرق اور فصل بدلنے کا خرچ خود درج کریں۔ قیمتیں ہم فرض نہیں کرتے۔ کم پانی کی ضرورت خود بخود زیادہ منافع نہیں بنتی۔':'To screen costs, enter your local variable pumping cost, crop-margin change and switching cost. We do not supply prices or yields. Lower water demand does not automatically mean higher profit.');
 const checks=language==='ur'?'بوائی سے پہلے مقامی زرعی ماہر سے فصل کا وقت، مٹی کی جانچ، نکاسی اور آبپاشی کا شیڈول دیکھیں۔ بیج، مزدور اور فصل کے خریدار کی تصدیق کریں۔ یہ نمونہ پنجاب پاکستان کے میدانی کھیتوں کے لیے ابتدائی مثال ہے، ہر جگہ کی حتمی سفارش نہیں۔':'Before planting, check local sowing windows, soil tests, drainage and irrigation timing with an agronomist. Confirm seeds, labour and a buyer. The crop examples target the irrigated plains of Punjab, Pakistan and are not a validated prescription for every farm.';
 if(topic==='water')return water;if(topic==='cost')return cost;if(topic==='checks')return checks;if(topic==='map')return language==='ur'?'علاقائی نقشے میں بارش، درجہ حرارت اور حسابی پانی کی کمی دیکھیں۔ ناسا کے خانے بڑے علاقے کے ہیں، کسی ایک کھیت کی پیمائش نہیں۔':'The map shows regional rainfall, temperature and modelled annual water gaps. NASA cells cover large areas; they are not measurements of one field.';
 return `${water} ${cost} ${checks}`;
}
